import{_ as o,l as i,o as e,c as l,v as r,p as n,x as t,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"OCI 镜像层","description":"","frontmatter":{"title":"OCI 镜像层","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/oci-image-layers.md","filePath":"cs/oci-image-layers.md","lastUpdated":1789023840000}'),h={name:"cs/oci-image-layers.md"};function f(u,a,m,_,g,v){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="oci-镜像层" tabindex="-1">OCI 镜像层 <a class="header-anchor" href="#oci-镜像层" aria-label="Permalink to &quot;OCI 镜像层&quot;">​</a></h1><div class="epigraph"><p>OCI 镜像是一叠 tar 层加配置：内容寻址，运行时用 [overlay](/cs/overlayfs) 或 fuse-overlay 合成可写视图。</p><footer>—— 据 OCI Image Spec；[overlayfs](/cs/overlayfs) 为联合挂载先修</footer></div><p><a href="/cs/container-runtime">runc</a> 需要 rootfs。缺口是 <strong>层</strong>：diff、digest、与 copy-up 如何对应打包。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每层 gzip tar，hash 为 id。配置：入口、env。缺口：删除文件用 whiteout；重复层共享存储；与 <a href="/cs/fs-snapshots">COW 快照</a> 不同——镜像层是 tar，不是 btrfs send 必选项。本课不把 registry 协议写完。</p><p><span class="marginnote">content store 按 digest 去重。对象是分发格式，不是 Dockerfile 语法课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>pull → 验证 digest → snapshotter 应用层 → 可写 upper。对照 <a href="/cs/sparse-files">稀疏</a>：层里可有空洞。对照 <a href="/cs/fsck">fsck</a>：坏层是校验失败。对照 LVM：块层快照不是镜像层。</p>',8)),(e(),n(d,null,{default:t(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAR%5B%22%E5%B1%82%20tar%22%5D%20--%3E%20DIG%5B%22digest%20%E5%AF%BB%E5%9D%80%22%5D%0A%20%20DIG%20--%3E%20OV%5B%22overlay%20%E5%90%88%E6%88%90%22%5D%0A%20%20OV%20--%3E%20ROOT%5B%22%E5%AE%B9%E5%99%A8%20rootfs%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>镜像层把文件系统差量化成可推送的不可变对象，使「构建一次到处跑」有存储几何。安全要验签名（与 <a href="/cs/kabi-module-signing">模块签名</a> 同构不同对象）。不要写成供应链产品。与 <a href="/cs/fs-quota">配额</a>：upper 可写层才涨。</p><p>过大层使启动慢，与 overlay 性能有关。</p><p>实现上：同一 digest 只存一份，构建缓存靠这个。whiteout 是 overlay 的删除表示，解到非 overlay 的 FS 要解释。配置与层分开哈希，改入口不必重写层。 读法上只引用<a href="/cs/container-runtime">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>OCI 镜像层</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 media type。不保证 Windows layer。下一课用用户态内核减攻击面：gVisor。</p><p>版本字段会变，课序钉的是机制对象「OCI 镜像层」，不是某一主线内核的结构体名。 后课默认：rootfs 是内容寻址层的合成。系统调用拦截式沙箱，下一课 gVisor。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OCI 镜像：寻址的层 + 配置。</li><li>运行时用 overlay 合成；whiteout 表达删除。</li><li>gVisor 是下一课。</li><li>出处：OCI image spec；overlayfs。</li></ul>',11))])}const T=o(h,[["render",f]]);export{I as __pageData,T as default};
